// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.eclipse.rdf4j.sail.lmdb.LmdbPackedRuleDifferentialSupport.check;

import java.io.File;
import java.util.List;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * LMDB publishes finite object domains for small predicates; a value-equality FILTER anchored on such a domain must
 * keep every stored term that SPARQL value-equals the constant (1, "01"^^xsd:integer and 1.0 all equal 1), and the
 * anchor's narrowed facts must never leak into sibling filters or enclosing joins.
 */
class LmdbFiniteAnchorValueEqualityTest {

	private static final String NON_CANONICAL_NUMERICS = """
			@prefix : <urn:t:> .
			@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
			:s1 :v 1 .
			:s2 :v "01"^^xsd:integer .
			:s3 :v 1.0 .
			:s4 :v 2 .
			:t1 :w 1.0 .
			""";

	@Test
	void finiteRangeAnchorKeepsValueEqualNonCanonicalTerms(@TempDir File dir) throws Exception {
		check(dir, NON_CANONICAL_NUMERICS, "SELECT ?s WHERE { ?s :v ?o FILTER(?o = 1) }",
				List.of("s=urn:t:s1", "s=urn:t:s2", "s=urn:t:s3"));
	}

	@Test
	void finiteRangeAnchorForDecimalConstantKeepsValueEqualTerms(@TempDir File dir) throws Exception {
		check(dir, NON_CANONICAL_NUMERICS, "SELECT ?s WHERE { ?s :v ?o FILTER(?o = 1.0) }",
				List.of("s=urn:t:s1", "s=urn:t:s2", "s=urn:t:s3"));
	}

	@Test
	void finiteRangeAnchorDoesNotPoisonSiblingFilterVerdict(@TempDir File dir) throws Exception {
		String data = """
				@prefix : <urn:t:> .
				:s1 :v 1 .
				:s3 :v 1.0 .
				:s4 :v 2 .
				""";
		check(dir, data, "SELECT ?s WHERE { ?s :v ?o FILTER(?o = 1) FILTER(datatype(?o) = xsd:decimal) }",
				List.of("s=urn:t:s3"));
	}

	@Test
	void anchorFactsDoNotPoisonEnclosingJoinDomain(@TempDir File dir) throws Exception {
		check(dir, NON_CANONICAL_NUMERICS, "SELECT ?s ?t WHERE { ?s :v ?o FILTER(?o = 1) ?t :w ?o }",
				List.of("s=urn:t:s3|t=urn:t:t1"));
	}

	@Test
	void anchorFactsDoNotPoisonEnclosingJoinDomainThroughNestedGroup(@TempDir File dir) throws Exception {
		check(dir, NON_CANONICAL_NUMERICS, "SELECT ?s ?t WHERE { { ?s :v ?o FILTER(?o = 1) } ?t :w ?o }",
				List.of("s=urn:t:s3|t=urn:t:t1"));
	}

	@Test
	void finiteFallbackFromValuesAnchorsEveryValueEqualConstant(@TempDir File dir) throws Exception {
		String data = """
				@prefix : <urn:t:> .
				:s1 :v 1 .
				:s3 :v 1.0 .
				:s4 :v 2 .
				""";
		check(dir, data, "SELECT ?s WHERE { VALUES ?o { 1 1.0 } ?s :v ?o FILTER(?o = 1) }",
				List.of("s=urn:t:s1", "s=urn:t:s3"));
	}

	@Test
	void finiteFallbackFromValuesDoesNotPoisonSiblingJoin(@TempDir File dir) throws Exception {
		String data = """
				@prefix : <urn:t:> .
				:s1 :v 1 .
				:s3 :v 1.0 .
				:s4 :v 2 .
				""";
		check(dir, data, "SELECT ?s WHERE { { VALUES ?o { 1 1.0 } ?s :v ?o FILTER(?o = 1) } VALUES ?o { 1.0 } }",
				List.of("s=urn:t:s3"));
	}

	@Test
	void constantValueEqualToNoStoredTermYieldsNoRows(@TempDir File dir) throws Exception {
		check(dir, NON_CANONICAL_NUMERICS, "SELECT ?s WHERE { ?s :v ?o FILTER(?o = 3) }", List.of());
	}
}
